<?php
 namespace QQWorld\Quote\Model\GuestCart; use QQWorld\Quote\Api\Data\CartItemInterface; use QQWorld\Quote\Api\CartItemRepositoryInterface; use QQWorld\Quote\Model\QuoteIdMask; use QQWorld\Quote\Model\QuoteIdMaskFactory; class GuestCartItemRepository implements \QQWorld\Quote\Api\GuestCartItemRepositoryInterface { protected $repository; protected $quoteIdMaskFactory; public function __construct( \QQWorld\Quote\Api\CartItemRepositoryInterface $repository, QuoteIdMaskFactory $quoteIdMaskFactory ) { $this->quoteIdMaskFactory = $quoteIdMaskFactory; $this->repository = $repository; } public function getList($cartId) { $quoteIdMask = $this->quoteIdMaskFactory->create()->load($cartId, 'masked_id'); $cartItemList = $this->repository->getList($quoteIdMask->getQuoteId()); foreach ($cartItemList as $item) { $item->setQuoteId($quoteIdMask->getMaskedId()); } return $cartItemList; } public function save(\QQWorld\Quote\Api\Data\CartItemInterface $cartItem) { $quoteIdMask = $this->quoteIdMaskFactory->create()->load($cartItem->getQuoteId(), 'masked_id'); $cartItem->setQuoteId($quoteIdMask->getQuoteId()); return $this->repository->save($cartItem); } public function deleteById($cartId, $itemId) { $quoteIdMask = $this->quoteIdMaskFactory->create()->load($cartId, 'masked_id'); return $this->repository->deleteById($quoteIdMask->getQuoteId(), $itemId); } } 